sys_script_include.script:
var TrainingUtils = Class.create();
TrainingUtils.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {
	refQualSchedule: function() {
		var schedulesNotToShow = [];
		var grRegister = new GlideRecord("x_1593179_traini_0_register");
		grRegister.addEncodedQuery("state!=4^opened_byDYNAMIC90d1921e5f510100a9ad2572f2b477fe");
		grRegister.query();
		while(grRegister.next()){
			schedulesNotToShow.push(grRegister.schedule.sys_id.toString());
		}

		var coursesWithLimitExceeded = [];
		var grRegisterCount = new GlideAggregate("x_1593179_traini_0_register");
		grRegisterCount.addEncodedQuery("opened_by=" + gs.getUserID());
		grRegisterCount.groupBy("schedule.course");
		grRegisterCount.addAggregate("COUNT");
		grRegisterCount.query();
		while (grRegisterCount.next()) {
			var course = grRegisterCount.getValue("schedule.course");
			var count = parseInt(grRegisterCount.getAggregate("COUNT"), 10);
			if (count >= 3) {
				coursesWithLimitExceeded.push(course);
			}
		}

		var schedulesFull = [];
		var grScheduleCount = new GlideAggregate("x_1593179_traini_0_register");
		grScheduleCount.addAggregate("COUNT");
		grScheduleCount.groupBy("schedule");
		grScheduleCount.addEncodedQuery("stateIN2,3");
		grScheduleCount.query();
		while (grScheduleCount.next()) {
			var scheduleId = grScheduleCount.getValue("schedule");
			var countSchedule = parseInt(grScheduleCount.getAggregate("COUNT"), 10);

			var grSchedule = new GlideRecord("x_1593179_traini_0_schedule");
			if (grSchedule.get(scheduleId) && countSchedule >= grSchedule.total_students) {
				schedulesFull.push(scheduleId);
			}
		}

		var schedulesToShow = [];
		var grSchedules = new GlideRecord("x_1593179_traini_0_schedule");
		grSchedules.addEncodedQuery("date>" + gs.endOfToday() + "^instructor.user!=" + gs.getUserID());
		grSchedules.query();
		while(grSchedules.next()){
			var courseId = grSchedules.course.toString();
			if(
				schedulesNotToShow.indexOf(grSchedules.getUniqueValue()) == -1 &&
				coursesWithLimitExceeded.indexOf(courseId) == -1 &&
				schedulesFull.indexOf(grSchedules.getUniqueValue()) == -1
			){
				schedulesToShow.push(grSchedules.getUniqueValue());
			}
		}

		return "sys_idIN" + schedulesToShow.join(",");

	},

    type: 'TrainingUtils'
});
